    const body = await this.apiHelper.parseJsonResponse<{ token?: string; reason?: string }>(response);
    if (!body.token) {
        throw new Error(`[BookingApi] /auth returned no token. Reason: ${body.reason ?? 'unknown'}`);
    }
    return body.token;
}


